window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-23a3a863ed7a7513"]={"versions": [{"id": "FIG-23a3a863ed7a7513", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung abstrakter Plattform-Datentypen in der AUTOSAR Adaptive Platform bzw. TPS Abstract Platform Specification. Das Diagramm definiert die Vererbungshierarchie von Anwendungsdatentypen ausgehend von AUTOSAR-Basismetaprofilen sowie die Typisierungsbeziehung zu Datenprototypen und Software-Datendefinitionseigenschaften.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Im Zentrum steht die abstrakte Metaklasse <code>AutosarDataType</code> (Spezialisierung von <code>ARElement</code> und <code>AtpType</code>). Sie besitzt eine Komposition zu <code>SwDataDefProps</code> (Rolle <code>+swDataDefProps</code>, Multiplizität <code>0..1</code>, mit Stereotyp <code>«atpVariation»</code>). Über die Assoziation <code>«isOfType»</code> verweist <code>AutosarDataPrototype</code> (abgeleitet von <code>DataPrototype</code>) mit der Rolle <code>+type</code> und der Multiplizität <code>1</code> (<code>{redefines atpType}</code>) auf <code>AutosarDataType</code>.</p>\n<p class=\"fig-p\"><code>ApplicationDataType</code> erbt von <code>AutosarDataType</code> sowie den Konzepten <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Sie fächert sich in zwei Subtypen auf:</p>\n<ul class=\"fig-list\"><li><code>ApplicationPrimitiveDataType</code>\n</li><li><code>ApplicationCompositeDataType</code> (abstrakt), welcher weiter spezialisiert wird durch:\n<ul class=\"fig-list\"><li><code>ApplicationRecordDataType</code>\n</li><li><code>ApplicationArrayDataType</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitverhalten. Die Modellierung beschreibt deklarative Datentyp- und Prototyp-Strukturen für Spezifikations- und Entwurfsartefakte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die Typdefinition in Schnittstellenbeschreibungen: Ein <code>AutosarDataPrototype</code> muss zwingend über die Rolle <code>+type</code> genau einem <code>AutosarDataType</code> zugeordnet sein (Kardinalität <code>1</code>). Anwendungsdatentypen können als Primitiv-, Record- oder Array-Strukturen angelegt und blueprints-fähig modelliert werden. Eigenschaften über <code>SwDataDefProps</code> sind optional und variabilitätsfähig (<code>«atpVariation»</code>).</p>"}, {"id": "FIG-a6da1b516b0cd3ce", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung abstrakter Plattform-Datentypen in der AUTOSAR Adaptive Platform bzw. TPS Abstract Platform Specification. Das Diagramm definiert die Vererbungshierarchie von Anwendungsdatentypen ausgehend von AUTOSAR-Basismetaprofilen sowie die Typisierungsbeziehung zu Datenprototypen und Software-Datendefinitionseigenschaften.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Im Zentrum steht die abstrakte Metaklasse <code>AutosarDataType</code> (Spezialisierung von <code>ARElement</code> und <code>AtpType</code>). Sie besitzt eine Komposition zu <code>SwDataDefProps</code> (Rolle <code>+swDataDefProps</code>, Multiplizität <code>0..1</code>, mit Stereotyp <code>«atpVariation»</code>). Über die Assoziation <code>«isOfType»</code> verweist <code>AutosarDataPrototype</code> (abgeleitet von <code>DataPrototype</code>) mit der Rolle <code>+type</code> und der Multiplizität <code>0..1</code> (<code>{redefines atpType}</code>) auf <code>AutosarDataType</code>.</p>\n<p class=\"fig-p\"><code>ApplicationDataType</code> erbt von <code>AutosarDataType</code> sowie den Konzepten <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Sie fächert sich in drei Subtypen auf:</p>\n<ul class=\"fig-list\"><li><code>ApplicationDeferredDataType</code>\n</li><li><code>ApplicationPrimitiveDataType</code>\n</li><li><code>ApplicationCompositeDataType</code> (abstrakt), welcher weiter spezialisiert wird durch:\n<ul class=\"fig-list\"><li><code>ApplicationRecordDataType</code>\n</li><li><code>ApplicationArrayDataType</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitverhalten. Die Modellierung beschreibt deklarative Datentyp- und Prototyp-Strukturen für Spezifikations- und Entwurfsartefakte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die Typdefinition in Schnittstellenbeschreibungen: Die Typisierung eines <code>AutosarDataPrototype</code> über die Rolle <code>+type</code> ist optional (Kardinalität <code>0..1</code>). Neben primitiven und zusammengesetzten Datentypen (<code>ApplicationPrimitiveDataType</code>, <code>ApplicationRecordDataType</code>, <code>ApplicationArrayDataType</code>) steht mit <code>ApplicationDeferredDataType</code> ein eigener Typ zur Modellierung verzögerter bzw. noch nicht ausdetaillierter Anwendungsdatentypen zur Verfügung. Eigenschaften über <code>SwDataDefProps</code> sind optional und variabilitätsfähig (<code>«atpVariation»</code>).</p>"}, {"id": "FIG-676b6656ca9d607f", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung abstrakter Plattform-Datentypen in der AUTOSAR Adaptive Platform bzw. TPS Abstract Platform Specification. Das Diagramm definiert die Vererbungshierarchie von Anwendungsdatentypen ausgehend von AUTOSAR-Basismetaprofilen sowie die Typisierungsbeziehung zu Datenprototypen und Software-Datendefinitionseigenschaften.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Im Zentrum steht die abstrakte Metaklasse <code>AutosarDataType</code> (Spezialisierung von <code>ARElement</code> und <code>AtpType</code>). Sie besitzt eine Komposition zu <code>SwDataDefProps</code> (Rolle <code>+swDataDefProps</code>, Multiplizität <code>0..1</code>, mit Stereotyp <code>«atpVariation»</code>). Über die Assoziation <code>«isOfType»</code> verweist <code>AutosarDataPrototype</code> (abgeleitet von <code>DataPrototype</code>) mit der Rolle <code>+type</code> und der Multiplizität <code>0..1</code> (<code>{redefines atpType}</code>) auf <code>AutosarDataType</code>.</p>\n<p class=\"fig-p\"><code>ApplicationDataType</code> erbt von <code>AutosarDataType</code> sowie den Konzepten <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Sie fächert sich in drei Subtypen auf:</p>\n<ul class=\"fig-list\"><li><code>ApplicationDeferredDataType</code>\n</li><li><code>ApplicationPrimitiveDataType</code>\n</li><li><code>ApplicationCompositeDataType</code> (abstrakt), welcher weiter spezialisiert wird durch:\n<ul class=\"fig-list\"><li><code>ApplicationRecordDataType</code>\n</li><li><code>ApplicationArrayDataType</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitverhalten. Die Modellierung beschreibt deklarative Datentyp- und Prototyp-Strukturen für Spezifikations- und Entwurfsartefakte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die Typdefinition in Schnittstellenbeschreibungen: Die Typisierung eines <code>AutosarDataPrototype</code> über die Rolle <code>+type</code> ist optional (Kardinalität <code>0..1</code>). Neben primitiven und zusammengesetzten Datentypen (<code>ApplicationPrimitiveDataType</code>, <code>ApplicationRecordDataType</code>, <code>ApplicationArrayDataType</code>) steht mit <code>ApplicationDeferredDataType</code> ein eigener Typ zur Modellierung verzögerter bzw. noch nicht ausdetaillierter Anwendungsdatentypen zur Verfügung. Eigenschaften über <code>SwDataDefProps</code> sind optional und variabilitätsfähig (<code>«atpVariation»</code>).</p>"}], "trans": [{"from": "FIG-23a3a863ed7a7513", "to": "FIG-a6da1b516b0cd3ce", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Hinzufügung der Spezialisierungsklasse <code>ApplicationDeferredDataType</code> als Subtyp von <code>ApplicationDataType</code>.\n</li><li>Änderung der Multiplizität der Assoziationsrolle <code>+type</code> (<code>«isOfType»</code>, <code>{redefines atpType}</code>) von <code>AutosarDataPrototype</code> zu <code>AutosarDataType</code> von <code>1</code> auf <code>0..1</code>.\n</li></ul>"}, {"from": "FIG-a6da1b516b0cd3ce", "to": "FIG-676b6656ca9d607f", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
